CREATE      VIEW [CE].[vwAccount]
AS 
SELECT 
	acc.[AccountId],
	acc.[rics_tradingname],
	acc.[rics_registeredname],
	acc.[name],
	acc.[Rics_AccountSubType],
	acc.[Rics_AccountSubTypeName],
	acc.[address1_postalcode],
	acc.[Address1_City],
	acc.[Address1_County],
	acc.[Address1_Country],
	acc.[address1_addresstypecode],
	acc.[address1_composite],
	acc.[address1_telephone1],
	acc.[address1_line3],
	acc.[address1_line2],
	acc.[address1_line1],
	acc.[rics_officenumber],
	acc.[Rics_LegalStatus],
	acc.[Rics_LegalStatusName],
	acc.[Rics_IsHeadoffice],
	acc.[rics_firmnumber],
	acc.[StatusCode],
	acc.[StatusCode_Description],
	acc.[StateCode],
	acc.[StateCode_Description],
	acc.[rics_namedaccount],
	acc.[rics_namedaccountName],
	acc.[CreatedBy],
	acc.[CreatedByName],
	acc.[Created_On],
	acc.[ModifiedBy],
	acc.[ModifiedByName],
	acc.[Modified_On],
	acc.[OwnerId],
	acc.[OwnerIdName],
	acc.[rics_countryid],
	cntry.[apuk_name] AS [rics_countryidName],
	acc.[PrimaryContactId],
	acc.[PrimaryContactIdName],
	acc.[Telephone1],
	acc.[ParentAccountId],
	acc.[ParentAccountIdName],
	acc.[AccountNumber],
	acc.[ricsv2_armareference],
	acc.[rics_yearestablished],
	acc.[websiteurl],
	acc.[rics_vatregnumber],
	acc.[apuk_vatgstregnumberrequired],
	acc.[apuk_companyregnorequired],
	acc.[apuk_companyregistrationnumber],
	acc.[msdyn_salestaxgroup],
	acc.[ricsv1_tradeaccount],
	acc.[numberofemployees],
	acc.[ricsv1_isregulatedoffice],
	acc.[emailaddress1],
	acc.[donotphone],
	acc.[donotpostalmail],
	acc.[donotfax],
	acc.[donotemail],
	acc.[donotbulkpostalmail],
	acc.[donotbulkemail],
	acc.[rics_corporatepayer],
	acc.[Rics_LocalGroupId],
	acc.[Rics_LocalGroupIdName],
	acc.[msdyn_invoiceaddress],
	acc.[msdyn_invoiceaddress_description],
	acc.[address1_longitude],
	acc.[address2_longitude],
	acc.[address1_latitude],
	acc.[address2_latitude],
	acc.[apuk_fasstatus],
	acc.[apuk_fasstatus_description],
	keyacc.[KeyAccount],
	keyacc.[KeyAccountManager] AS [Key Account Manager],
	acc.[rics_namedaccount] AS apuk_commercialaccountid,
	acc.[customer_payment_method]
FROM [synapse_ce].[vwAccount] acc
	LEFT JOIN [synapse_ce].[vwCountry] cntry
		ON acc.[rics_countryid] = cntry.[apuk_countryid]
	LEFT JOIN [CE].[tblAccount_KeyAccounts] keyacc
		ON acc.[AccountId] = keyacc.[AccountId]
